861	  /// `@`'s full description, for prefilling the dialog.
862	  ///
863	  /// Read-only, so it carries `jjReadFlags`: without `--ignore-working-copy` this would snapshot the
864	  /// working copy and take its lock, ungated, just to populate a text field.
865	  ///
866	  /// The FULL description, not `JJCommitChanges.description`, which is only the first line — filling
867	  /// the summary from that and then running Describe would silently discard the message body.
868	  static func jjDescriptionArgs() -> [String] {
869	    ["log", "-r", "@", "--no-graph"] + jjReadFlags + ["-T", "description"]
870	  }
871	
872	  /// The jj operation id at the head of the op log, for the same before/after comparison
873	  /// `gitHeadArgs` serves.
874	  static func jjOpHeadArgs() -> [String] {
875	    ["op", "log", "--no-graph"] + jjReadFlags + ["--limit", "1", "-T", "self.id().short()"]
876	  }
877	
878	  /// Which revision an anonymous push should send.
879	  ///
880	  /// `@` when it carries work, otherwise its parent. jj refuses to push a commit with an empty
881	  /// description, and a fresh `@` after `jj new` has neither changes nor a description — so pushing
882	  /// `@` blindly fails for the most common state a workroom sits in.
883	  static func jjPushRevision(hasChanges: Bool, hasDescription: Bool) -> String {
884	    (hasChanges || hasDescription) ? "@" : "@-"
885	  }
