887	  // MARK: - Parsers
888	
889	  struct RemoteRefs: Equatable, Sendable {
890	    /// Remote names, first-seen order (so `origin` keeps its natural primacy when present).
891	    let remotes: [String]
892	    /// Short names, e.g. `"origin/main"`.
893	    let shortNames: Set<String>
894	  }
895	
896	  /// Parse `for-each-ref refs/remotes` output.
897	  ///
898	  /// Skips records with a non-empty `%(symref)` — that's `refs/remotes/<remote>/HEAD`, whose short
899	  /// name is the bare remote and which would otherwise look like a branch called `origin`.
900	  /// Field count is checked rather than assumed: a ref name can't contain a control character, but
901	  /// being strict here means a malformed line is dropped rather than crashing the read.
902	  static func parseGitRemoteRefs(_ stdout: String) -> RemoteRefs {
903	    var remotes: [String] = []
904	    var shortNames: Set<String> = []
905	    for line in stdout.split(whereSeparator: \.isNewline) {
906	      let fields = line.components(separatedBy: "\0")
907	      guard fields.count == 3 else { continue }
908	      guard fields[2].isEmpty else { continue }  // symref → origin/HEAD
909	      let refname = fields[0]
910	      let prefix = "refs/remotes/"
911	      guard refname.hasPrefix(prefix) else { continue }
912	      let short = String(refname.dropFirst(prefix.count))
913	      guard let slash = short.firstIndex(of: "/") else { continue }
914	      let remote = String(short[short.startIndex..<slash])
915	      guard !remote.isEmpty, slash < short.index(before: short.endIndex) else { continue }
916	      if !remotes.contains(remote) { remotes.append(remote) }
917	      shortNames.insert(short)
918	    }
919	    return RemoteRefs(remotes: remotes, shortNames: shortNames)
920	  }
921	
922	  /// `git remote` output → remote names, listed order preserved.
923	  static func parseGitRemoteList(_ stdout: String) -> [String] {
924	    var remotes: [String] = []
925	    for line in stdout.split(whereSeparator: \.isNewline) {
926	      let name = line.trimmingCharacters(in: .whitespaces)
927	      guard !name.isEmpty, !remotes.contains(name) else { continue }
928	      remotes.append(name)
929	    }
930	    return remotes
931	  }
932	
933	  /// `jj git remote list` output (`<name> <url>` per line) → remote names, listed order preserved.
934	  ///
935	  /// Split on the LAST space, not the first: jj accepts a remote name containing spaces (the same
936	  /// permissiveness `jjQuote` exists for), while a URL has none.
